	@GetMapping("/generate-life-certificate-approver")
	public ResponseEntity<byte[]> getPensionersByPensionerIdByApprover(@RequestParam("pensionerId") String pensionerId,
			@RequestParam("dept") String dept) {

		HttpHeaders headers = new HttpHeaders();
		headers.setContentType(MediaType.APPLICATION_PDF);
		byte[] pdfBytes = null;
		logger.info("request from t-app log ==>> pensionerId is " + pensionerId + " department is " + dept);
		Map<String, Object> data = pdfGeneratorService.getByPensionerIdForPDFByApproved(pensionerId, dept);
		if (data != null) {		
			
			String re_marriage = (String) data.get("re_marriage");

			if (dept.equalsIgnoreCase("TGGENCO")) {
				 if ("Yes".equalsIgnoreCase(re_marriage)) {
					 	pdfBytes = pdfGeneratorService.generatePdf("TGGENCOfam", data);
				 }else {
					 pdfBytes = pdfGeneratorService.generatePdf("TGGENCO", data);
				 }
			}

			if (dept.equalsIgnoreCase("TGNPDCL")) {
				 if ("Yes".equalsIgnoreCase(re_marriage)) {
					 	pdfBytes = pdfGeneratorService.generatePdf("NPDCLfam", data);
				 }else {
		              pdfBytes = pdfGeneratorService.generatePdf("TGNPDCL", data);
				 }
			}
			
			if (dept.equalsIgnoreCase("TGSPDCL")) {
				if ("Yes".equalsIgnoreCase(re_marriage)) {
						pdfBytes = pdfGeneratorService.generatePdf("TGSPDCLfam", data);
				}else {
					  pdfBytes = pdfGeneratorService.generatePdf("TGSPDCL", data);
				}
			}
			
			if (dept.equalsIgnoreCase("TGTRANSCO")) {
				if ("Yes".equalsIgnoreCase(re_marriage)) {
						pdfBytes = pdfGeneratorService.generatePdf("TGTRANSCOfam", data);
				}else {
					 pdfBytes = pdfGeneratorService.generatePdf("TGTRANSCO", data);
				}
			}

			headers.setContentDispositionFormData("filename", pensionerId + ".pdf");

		} else {
			return new ResponseEntity<>(pdfBytes, headers, HttpStatus.BAD_REQUEST);
		}
		return new ResponseEntity<>(pdfBytes, headers, HttpStatus.OK);

	}

	@GetMapping("/generate-life-certificate-verifier")
	public ResponseEntity<byte[]> getPensionersByPensionerIdbyVerifier(@RequestParam("pensionerId") String pensionerId,
			@RequestParam("dept") String dept) {

		HttpHeaders headers = new HttpHeaders();
		headers.setContentType(MediaType.APPLICATION_PDF);
		byte[] pdfBytes = null;
		logger.info("request from t-app log ==>> pensionerId is " + pensionerId + " department is " + dept);
		Map<String, Object> data = pdfGeneratorService.getByPensionerIdForPDFByVerifier(pensionerId, dept);
		if (data != null) {

			if (dept.equalsIgnoreCase("TGGENCO")) {
				pdfBytes = pdfGeneratorService.generatePdf("TGGENCO", data);

			}

			if (dept.equalsIgnoreCase("TGNPDCL")) {
				pdfBytes = pdfGeneratorService.generatePdf("TGNPDCL", data);

			}
			if (dept.equalsIgnoreCase("TGSPDCL")) {
				pdfBytes = pdfGeneratorService.generatePdf("TGSPDCL", data);

			}
			if (dept.equalsIgnoreCase("TGTRANSCO")) {
				pdfBytes = pdfGeneratorService.generatePdf("TGTRANSCO", data);

			}

			headers.setContentDispositionFormData("filename", pensionerId + ".pdf");

		} else {
			return new ResponseEntity<>(pdfBytes, headers, HttpStatus.BAD_REQUEST);
		}
		return new ResponseEntity<>(pdfBytes, headers, HttpStatus.OK);

	}

	@GetMapping("/download-pensioners-ByApprover")
	public ResponseEntity<ByteArrayResource> downloadPensionerListByApprover(
			@RequestParam("approverOfficerCode") String approverOfficerCode,
			@RequestParam("deptCode") String deptCode) {

		// Fetch pensioners list based on the parameters
		List<GetMatchedDetails> pensioners = approverService
				.getPensionersByApproverOfficerCodeByApproved(approverOfficerCode, deptCode);

		// Generate HTML content using Thymeleaf
		Context context = new Context();
		context.setVariable("pensioners", pensioners);
		String htmlContent = templateEngine.process("pensioner-list", context);

		// Generate PDF
		ByteArrayOutputStream pdfOutputStream = new ByteArrayOutputStream();
		try {
			PdfRendererBuilder builder = new PdfRendererBuilder();
			builder.useFastMode();
			builder.withHtmlContent(htmlContent, null);
			builder.toStream(pdfOutputStream);
			builder.run();
		} catch (Exception e) {
			throw new RuntimeException("Error while generating PDF", e);
		}

		// Convert to ByteArrayResource for multiple reads
		ByteArrayResource pdfResource = new ByteArrayResource(pdfOutputStream.toByteArray());

		// Return the PDF as a downloadable response
		HttpHeaders headers = new HttpHeaders();
		headers.add("Content-Disposition", "attachment; filename=pensioner-list.pdf");

		return ResponseEntity.ok().headers(headers).contentType(MediaType.APPLICATION_PDF)
				.contentLength(pdfResource.contentLength()).body(pdfResource);
	}

